package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type AmtRec struct {
	ArAcct string
	ArAmt  decimal.Decimal
}

var WsEofFlag string = "N"
var WsBigTotal decimal.Decimal = decimal.NewFromInt(0)
var WsWrapTotal decimal.Decimal = decimal.NewFromInt(0)
var WsSafeTotal decimal.Decimal = decimal.NewFromInt(0)
var WsOverflows int64 = 0
var WsCount int64 = 0
var WsHalf decimal.Decimal = decimal.NewFromInt(0)
var WsAmtEd string
var WsWrapEd string
var WsSafeEd string
var WsHalfEd string

var amtFile *os.File
var amtScanner *bufio.Scanner
var amtRec AmtRec

func InputDone() bool { return WsEofFlag == "Y" }

func storeWrap(val decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	t := val.Truncate(scale)
	mod := decimal.NewFromInt(1).Shift(int32(intDigits))
	// keep low order digits via Mod (handles positive and negative)
	if t.Abs().GreaterThanOrEqual(mod) {
		// decimal.Mod keeps sign of dividend
		t = t.Mod(mod)
	}
	return t
}

func isOverflow(val decimal.Decimal, intDigits int, scale int32) bool {
	t := val.Truncate(scale)
	mod := decimal.NewFromInt(1).Shift(int32(intDigits))
	return t.Abs().GreaterThanOrEqual(mod)
}

func formatZZZZ9_99(val decimal.Decimal) string {
	// picture ZZ,ZZ9.99  intDigits=5 scale=2 comma after 2 digits
	return formatEdited(val, 5, 2, map[int]bool{2: true})
}

func formatZZZZ9_9(val decimal.Decimal) string {
	return formatEdited(val, 5, 1, map[int]bool{2: true})
}

func formatEdited(val decimal.Decimal, intDigits int, scale int32, commaAfter map[int]bool) string {
	// val already truncated to scale and wrapped
	neg := val.IsNegative()
	abs := val.Abs()
	// integer part
	intPart := abs.Truncate(0)
	// build intStr zero padded
	intStr := intPart.String() // decimal without exponent, no fractional
	// String may lack leading zeros; pad
	// intPart may be large but intDigits is max, it is already wrapped so fits
	if len(intStr) > intDigits {
		// high digits dropped already, but just in case keep low digits
		intStr = intStr[len(intStr)-intDigits:]
	}
	intStr = fmt.Sprintf("%0*s", intDigits, intStr)

	// fractional part
	fracStr := ""
	if scale > 0 {
		// get fractional digits: abs - intPart
		frac := abs.Sub(intPart)
		// frac * 10^scale truncated
		mult := decimal.NewFromInt(1).Shift(scale)
		fracInt := frac.Mul(mult).Truncate(0)
		fracStr = fracInt.String()
		// fracStr may be like "0" etc, pad
		fracStr = fmt.Sprintf("%0*s", scale, fracStr)
		if len(fracStr) > int(scale) {
			fracStr = fracStr[len(fracStr)-int(scale):]
		}
	}

	// picture type for each int position: 9 for last, Z otherwise
	picIs9 := make([]bool, intDigits)
	for i := 0; i < intDigits; i++ {
		picIs9[i] = false
	}
	picIs9[intDigits-1] = true // last is 9

	// Build integer output with commas
	// output positions: intDigits + numCommas
	numCommas := len(commaAfter)
	outIntLen := intDigits + numCommas
	outInt := make([]rune, outIntLen)

	// map int idx -> out pos
	// we have commaAfter key = number of int digits before comma
	// for our case 2 means after idx 1 (0-based) => position
	// General: iterate int idx and place commas

	// Create mapping
	outPos := 0
	intIdxToOutPos := make(map[int]int)
	for idx := 0; idx < intDigits; idx++ {
		intIdxToOutPos[idx] = outPos
		outPos++
		// check if comma after this idx+1 digits
		if commaAfter[idx+1] {
			outPos++ // comma position
		}
	}

	// Determine suppression: Z positions with leading zeros become spaces
	// Find first non-zero int digit
	firstNonZero := -1
	for i := 0; i < intDigits; i++ {
		if intStr[i] != '0' {
			firstNonZero = i
			break
		}
	}
	// if all zeros, firstNonZero stays -1, but the 9 position must still show 0

	for idx := 0; idx < intDigits; idx++ {
		pos := intIdxToOutPos[idx]
		ch := rune(intStr[idx])
		if picIs9[idx] {
			outInt[pos] = ch
		} else {
			// Z
			if firstNonZero == -1 {
				// all zeros, suppress
				outInt[pos] = ' '
			} else {
				if idx < firstNonZero {
					outInt[pos] = ' '
				} else {
					outInt[pos] = ch
				}
			}
		}
	}
	// fill commas
	// comma positions are after idx; outPos = intIdxToOutPos[idx]+1
	for k := range commaAfter {
		// k is digits before comma, so comma after idx = k-1
		idx := k - 1
		if idx < 0 || idx >= intDigits-1 {
			continue
		}
		cPos := intIdxToOutPos[idx] + 1
		// comma is suppressed (space) if all int digits up to idx are suppressed (i.e., no non-zero before comma)
		suppressComma := true
		if firstNonZero != -1 && firstNonZero <= idx {
			suppressComma = false
		} else {
			// also if firstNonZero is after comma but still zeros before, then comma is in suppressed zone
			// So remains suppressed
		}
		if suppressComma {
			outInt[cPos] = ' '
		} else {
			outInt[cPos] = ','
		}
	}

	intPartFormatted := string(outInt)
	if scale > 0 {
		res := intPartFormatted + "." + fracStr
		if neg {
			// For COBOL edited with no sign, negative would need minus; not needed here
			// just prepend minus (will shift) - not used
			res = "-" + res
		}
		return res
	}
	return intPartFormatted
}

func parseArAmt(s string) decimal.Decimal {
	// s is exactly 7 chars (padded with spaces)
	s = strings.TrimSpace(s)
	if s == "" {
		return decimal.NewFromInt(0)
	}
	// keep only digits, handle sign? not needed
	// s may contain digits only
	// if contains non-digit, treat as 0? just parse digits
	clean := ""
	for _, r := range s {
		if r >= '0' && r <= '9' {
			clean += string(r)
		}
	}
	if clean == "" {
		return decimal.NewFromInt(0)
	}
	// clean length may be up to 7, but we interpret as 9(5)V99 => scale 2
	// If shorter, pad left with zeros? Actually LINE SEQUENTIAL padded with spaces on right, so numeric field missing would be spaces.
	// Use clean as integer value, New with exponent -2
	// However if clean length <7, it means leading zeros omitted? We'll just parse as given and adjust? For 7-digit field, "0001000" = 10.00? Let's parse directly.
	// Need to handle clean length !=7: still scale 2 (implied decimal)
	// So value = int(clean) *10^-2
	// But if input file contains 7 chars with digits, clean length 7, correct.
	// If input had shorter because trailing spaces trimmed? Our clean would be correct.

	// Parse as integer
	d, err := decimal.NewFromString(clean)
	if err != nil {
		return decimal.NewFromInt(0)
	}
	d = d.Shift(-2)
	return d
}

func MAIN_PARA() {
	amtFile, err := os.Open("input.dat")
	if err != nil {
		// if file missing, treat as empty
		WsEofFlag = "Y"
	} else {
		amtScanner = bufio.NewScanner(amtFile)
		// allow long lines
		READ_PARA()
		for !InputDone() {
			PROCESS_PARA()
		}
		amtFile.Close()
	}
	SUMMARY_PARA()
}

func READ_PARA() {
	if amtScanner == nil {
		WsEofFlag = "Y"
		return
	}
	if !amtScanner.Scan() {
		WsEofFlag = "Y"
		return
	}
	line := amtScanner.Text()
	// pad with spaces to 11
	if len(line) < 11 {
		line = line + strings.Repeat(" ", 11-len(line))
	} else if len(line) > 11 {
		line = line[:11]
	}
	amtRec.ArAcct = line[0:4]
	amtRec.ArAmt = parseArAmt(line[4:11])
}

func PROCESS_PARA() {
	// ADD AR-AMT TO WS-BIG-TOTAL (wrapping)
	sumBig := WsBigTotal.Add(amtRec.ArAmt)
	WsBigTotal = storeWrap(sumBig, 7, 2)

	// MOVE WS-BIG-TOTAL TO WS-WRAP-TOTAL (drop high digits)
	WsWrapTotal = storeWrap(WsBigTotal, 5, 2)

	// ADD AR-AMT TO WS-SAFE-TOTAL ON SIZE ERROR PERFORM OVERFLOW-PARA
	sumSafe := WsSafeTotal.Add(amtRec.ArAmt)
	if isOverflow(sumSafe, 5, 2) {
		OVERFLOW_PARA()
	} else {
		WsSafeTotal = sumSafe.Truncate(2)
	}

	// ADD 1 TO WS-COUNT (wrapping, PIC 99)
	sumCount := WsCount + 1
	// low-order 2 digits
	WsCount = sumCount % 100

	// COMPUTE WS-HALF = AR-AMT / 2 truncated
	divisor := decimal.NewFromInt(2)
	halfRaw := amtRec.ArAmt.Div(divisor)
	WsHalf = storeWrap(halfRaw, 5, 1)

	// MOVE to edited
	WsAmtEd = formatZZZZ9_99(storeWrap(amtRec.ArAmt, 5, 2))
	WsWrapEd = formatZZZZ9_99(WsWrapTotal)
	WsSafeEd = formatZZZZ9_99(WsSafeTotal)
	WsHalfEd = formatZZZZ9_9(WsHalf)

	fmt.Printf("%s %s %s %s %s\n", amtRec.ArAcct, WsAmtEd, WsWrapEd, WsSafeEd, WsHalfEd)

	READ_PARA()
}

func SUMMARY_PARA() {
	fmt.Printf("RECORDS: %02d\n", WsCount)
	fmt.Printf("OVERFLOWS: %02d\n", WsOverflows)
}

func OVERFLOW_PARA() {
	WsOverflows = (WsOverflows + 1) % 100
}

func main() {
	MAIN_PARA()
}
